-- VIS-128: run against a disposable/local database with migrations applied.
begin;
create or replace function pg_temp.check(ok boolean, label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
update public.ai_credit_settings set signup_grant=0,generation_cost=100;
insert into auth.users(id,email) values ('12800000-0000-4000-8000-000000000001','repair@example.invalid');
select public.grant_ai_credits('12800000-0000-4000-8000-000000000001',1000,'discretionary','repair-test');
select pg_temp.check(not has_function_privilege('authenticated','public.charge_ai_repair(uuid,integer)','EXECUTE'),'Clients cannot charge repairs directly');
select public.begin_ai_generation('12800000-0000-4000-8000-000000000010','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select pg_temp.check(public.charge_ai_repair('12800000-0000-4000-8000-000000000010',99)='price_changed','Stale quoted price rejected');
select pg_temp.check(not exists(select 1 from public.ai_credit_transactions where generation_request_id='12800000-0000-4000-8000-000000000010'),'Stale price incurs no charge');
select pg_temp.check(public.charge_ai_repair('12800000-0000-4000-8000-000000000010',100)='charged','Repair charged before model');
select pg_temp.check(public.ai_available_credits('12800000-0000-4000-8000-000000000001')=900,'Charge does not double subtract reservation');
select pg_temp.check(public.charge_ai_repair('12800000-0000-4000-8000-000000000010',100)='already_charged','Duplicate charge cannot start another attempt');
select public.complete_ai_generation('12800000-0000-4000-8000-000000000010','exhausted',1,'broken candidate');
select pg_temp.check(public.ai_available_credits('12800000-0000-4000-8000-000000000001')=900,'Failed repair remains charged');
select pg_temp.check((select status='exhausted' and generated_source='broken candidate' and repair_charged from public.ai_generation_requests where id='12800000-0000-4000-8000-000000000010'),'Failed repair retains real status and downloadable candidate');
select public.begin_ai_generation('12800000-0000-4000-8000-000000000011','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select public.charge_ai_repair('12800000-0000-4000-8000-000000000011',100);
select public.complete_ai_generation('12800000-0000-4000-8000-000000000011','success',1,'render {}');
select pg_temp.check((select count(*)=1 and sum(amount)=-100 from public.ai_credit_transactions where generation_request_id='12800000-0000-4000-8000-000000000011'),'Successful repair charged exactly once');
select public.begin_ai_generation('12800000-0000-4000-8000-000000000012','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select public.complete_ai_generation('12800000-0000-4000-8000-000000000012','exhausted',2);
select pg_temp.check(public.ai_available_credits('12800000-0000-4000-8000-000000000001')=800,'Ordinary failed generation remains free');
select public.begin_ai_generation('12800000-0000-4000-8000-000000000013','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select public.charge_ai_repair('12800000-0000-4000-8000-000000000013',100);
select public.complete_ai_generation('12800000-0000-4000-8000-000000000013','error',1);
select pg_temp.check(public.ai_available_credits('12800000-0000-4000-8000-000000000001')=700,'Provider failure remains charged');
select public.begin_ai_generation('12800000-0000-4000-8000-000000000014','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select public.charge_ai_repair('12800000-0000-4000-8000-000000000014',100);
update public.ai_generation_requests set created_at=now()-interval '11 minutes' where id='12800000-0000-4000-8000-000000000014';
select public.complete_ai_generation('12800000-0000-4000-8000-000000000014','aborted',1);
select pg_temp.check(public.ai_available_credits('12800000-0000-4000-8000-000000000001')=600,'Abandoned repair remains charged');
update public.profiles set ai_credit_exempt=true where id='12800000-0000-4000-8000-000000000001';
select public.begin_ai_generation('12800000-0000-4000-8000-000000000015','12800000-0000-4000-8000-000000000001',repeat('a',64),100,100,3600,10);
select pg_temp.check(public.charge_ai_repair('12800000-0000-4000-8000-000000000015',0)='charged','Exemption retained for repair');
select public.complete_ai_generation('12800000-0000-4000-8000-000000000015','error',1);
select pg_temp.check(not exists(select 1 from public.ai_credit_transactions where generation_request_id='12800000-0000-4000-8000-000000000015'),'Exempt repair has no debit');
rollback;
